package cn.huankan.event;

import java.util.*;
import java.time.Instant;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;

@Service
public class ResearchService {
    private final JdbcTemplate db;private final com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper();
    public ResearchService(JdbcTemplate db,@org.springframework.beans.factory.annotation.Value("${huankan.collector-enabled}") boolean enabled){this.db=db;}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("研究结果序列化失败",e);}}
    @Transactional public Map<String,Object> process(boolean reprocess,int limit){
        if(limit<1||limit>1000)throw new IllegalArgumentException("处理批次应在1至1000之间");
        // Transactional lease avoids concurrent workers and bounded batches protect collection.
        db.execute("SELECT pg_advisory_xact_lock(742022)");
        if(reprocess)db.update("UPDATE event_candidate SET rule_version='待重处理' WHERE rule_version=?",ResearchRules.VERSION);
        var rows=db.queryForList("SELECT e.id,e.document_id,e.evidence_id,e.original_title,e.source_id,r.source_url,r.published_at,s.level,d.themes,d.underlying_url,p.canonical_source_url,p.canonical_equivalence_confirmed FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id LEFT JOIN aggregated_dependency d ON d.evidence_id=r.id LEFT JOIN evidence_provenance p ON p.evidence_id=r.id LEFT JOIN event_candidate c ON c.event_id=e.id WHERE c.event_id IS NULL OR c.evidence_id<>e.evidence_id OR c.rule_version<>? ORDER BY r.ingested_at,e.id LIMIT ?",ResearchRules.VERSION,limit);
        for(var row:rows){String url=Objects.toString(row.get("underlying_url"),Boolean.TRUE.equals(row.get("canonical_equivalence_confirmed"))?Objects.toString(row.get("canonical_source_url")):row.get("source_url").toString());var rule=ResearchRules.evaluate(row.get("original_title").toString(),Objects.toString(row.get("themes"),""),url,row.get("level").toString(),row.get("evidence_id").toString());
            if("ECB_DATA".equals(row.get("source_id")))rule=ResearchRules.observation(rule,row.get("document_id").toString());
            db.update("INSERT INTO event_candidate(event_id,evidence_id,rule_version,topics,score,score_basis,cluster_key,cluster_basis,source_host) VALUES(?,?,?,?::jsonb,?,?::jsonb,?,?,?) ON CONFLICT(event_id) DO UPDATE SET evidence_id=excluded.evidence_id,rule_version=excluded.rule_version,topics=excluded.topics,score=excluded.score,score_basis=excluded.score_basis,cluster_key=excluded.cluster_key,cluster_basis=excluded.cluster_basis,source_host=excluded.source_host,verification=CASE WHEN event_candidate.evidence_id=excluded.evidence_id THEN event_candidate.verification ELSE 'PENDING' END,processed_at=now()",row.get("id"),row.get("evidence_id"),ResearchRules.VERSION,encode(rule.topics()),rule.score(),encode(rule.basis()),rule.clusterKey(),rule.clusterBasis(),rule.host());
            // A related official URL is only a review candidate, never an automatic fact upgrade.
            db.update("INSERT INTO candidate_official_evidence(event_id,evidence_id,reason) SELECT ?,r.id,'原文URL精确匹配；同一事实待人工核验' FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id WHERE s.level='L0' AND r.source_url=? AND r.id<>? ON CONFLICT DO NOTHING",row.get("id"),url,row.get("evidence_id"));
            identify(row);
        }return Map.of("processed",rows.size(),"rule_version",ResearchRules.VERSION);
    }
    private void identify(Map<String,Object> row){
        // Match names explicitly present in real evidence; no fabricated corporate master data.
        var bytes=db.queryForObject("SELECT raw_content FROM raw_evidence WHERE id=?",byte[].class,row.get("evidence_id"));String raw=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);String source=row.get("source_id").toString();
        String official=switch(source){case "FED"->"Federal Reserve";case "ECB","ECB_DATA"->"European Central Bank";case "NBS"->"国家统计局";default->null;};
        if(official!=null&&raw.contains(official)){
            String name=switch(source){case "FED"->"美联储";case "NBS"->"国家统计局";default->"欧洲央行";};String type=source.equals("NBS")?"ORGANIZATION":"CENTRAL_BANK";
            UUID entity=db.queryForObject("INSERT INTO financial_entity(id,type,official_name,identity_key,english_name,chinese_name,source_id,source_url,evidence_id,status) VALUES(?,?,?,?,?,?,?,?,?,'VERIFIED') ON CONFLICT(type,source_id,identity_key) DO UPDATE SET official_name=excluded.official_name RETURNING id",UUID.class,UUID.randomUUID(),type,official,official,source.equals("NBS")?null:official,name,source,row.get("source_url"),row.get("evidence_id"));
            db.update("INSERT INTO event_entity(event_id,entity_id,evidence_id,match_basis,status) VALUES(?,?,?,'官方响应包含机构名称；标识发布来源，不推定为事件主体','VERIFIED') ON CONFLICT DO NOTHING",row.get("id"),entity,row.get("evidence_id"));
        }
        if(source.equals("GDELT"))for(String organizations:db.queryForList("SELECT organizations FROM aggregated_dependency WHERE evidence_id=?",String.class,row.get("evidence_id"))){if(organizations==null)continue;for(String name:Arrays.stream(organizations.split(";")).map(String::strip).filter(n->!n.isEmpty()&&n.length()<=200).distinct().limit(20).toList()){
            UUID entity=db.queryForObject("INSERT INTO financial_entity(id,type,official_name,identity_key,source_id,source_url,evidence_id,status) VALUES(?,'ORGANIZATION',?,?,'GDELT',?,?,'PENDING') ON CONFLICT(type,source_id,identity_key) DO UPDATE SET official_name=excluded.official_name RETURNING id",UUID.class,UUID.randomUUID(),name,row.get("id")+":"+name,row.get("source_url"),row.get("evidence_id"));
            db.update("INSERT INTO event_entity(event_id,entity_id,evidence_id,match_basis) VALUES(?,?,?,'GKG机构索引字符串候选；机构类型与同名身份尚未确认') ON CONFLICT DO NOTHING",row.get("id"),entity,row.get("evidence_id"));
        }}
    }
    public Map<String,Object> candidates(int page,String topic){return candidates(page,topic,false);}
    public Map<String,Object> candidates(int page,String topic,boolean officialOnly){if(page<0||page>100000||topic==null||topic.length()>100)throw new IllegalArgumentException("查询参数无效");String where=" WHERE EXISTS(SELECT 1 FROM financial_event scope WHERE scope.id=c.event_id AND scope.source_id NOT IN('ECB_DATA','FRED')"+(officialOnly?" AND scope.source_id<>'GDELT'":"")+") AND (?='' OR c.topics @> jsonb_build_array(?::text))";return Map.of("items",db.queryForList("SELECT c.*,e.original_title,e.chinese_title,e.source_id,r.source_url,r.published_at,r.first_seen_at,r.collected_at,s.name source_name,s.level,d.underlying_url,(SELECT count(*) FROM event_candidate x WHERE x.cluster_key=c.cluster_key) article_group_size FROM event_candidate c JOIN financial_event e ON e.id=c.event_id JOIN raw_evidence r ON r.id=c.evidence_id JOIN source_registry s ON s.id=e.source_id LEFT JOIN aggregated_dependency d ON d.evidence_id=r.id"+where+" ORDER BY c.score DESC,r.published_at DESC NULLS LAST,c.event_id LIMIT 50 OFFSET ?",topic,topic,page*50),"total",db.queryForObject("SELECT count(*) FROM event_candidate c"+where,Long.class,topic,topic));}
    public Map<String,Object> detail(UUID id){var result=new LinkedHashMap<String,Object>();result.put("event",db.queryForMap("SELECT e.*,r.source_url,r.published_at,r.first_seen_at,r.collected_at,r.raw_content_hash,r.verification_status,s.level,s.name source_name,c.topics,c.score,c.score_basis,c.rule_version,c.cluster_basis,c.verification research_verification FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id LEFT JOIN event_candidate c ON c.event_id=e.id WHERE e.id=?",id));result.put("entities",db.queryForList("SELECT n.*,m.status match_status,m.match_basis FROM event_entity m JOIN financial_entity n ON n.id=m.entity_id WHERE m.event_id=? ORDER BY n.official_name LIMIT 100",id));result.put("relations",db.queryForList("SELECT r.*,a.official_name subject,b.official_name object FROM entity_relation r JOIN financial_entity a ON a.id=r.subject_id JOIN financial_entity b ON b.id=r.object_id WHERE (r.subject_id IN(SELECT entity_id FROM event_entity WHERE event_id=?) OR r.object_id IN(SELECT entity_id FROM event_entity WHERE event_id=?)) AND (r.status<>'VERIFIED' OR EXISTS(SELECT 1 FROM financial_event e JOIN raw_evidence p ON p.id=e.evidence_id WHERE e.id=? AND p.published_at IS NOT NULL AND r.disclosed_at<=p.published_at AND r.first_public_at<=p.published_at AND (r.effective_from IS NULL OR r.effective_from<=p.published_at) AND (r.effective_until IS NULL OR r.effective_until>p.published_at))) ORDER BY r.id LIMIT 100",id,id,id));result.put("official_evidence",db.queryForList("SELECT c.*,r.source_url,r.published_at,r.raw_content_hash FROM candidate_official_evidence c JOIN raw_evidence r ON r.id=c.evidence_id WHERE c.event_id=?",id));result.put("reviews",db.queryForList("SELECT * FROM research_review WHERE target_id=? ORDER BY id DESC LIMIT 50",id));result.put("versions",db.queryForList("SELECT r.id,r.source_url,r.raw_content_hash,r.revision,r.published_at,r.collected_at,r.ingestion_kind FROM event_evidence x JOIN raw_evidence r ON r.id=x.evidence_id WHERE x.event_id=? ORDER BY r.revision DESC LIMIT 100",id));result.put("uncertainty",List.of("主题来自标题或聚合索引，未提取完整指标数值","文章组仅表示同一URL，不证明各报道指向同一经济事实","没有授权行情，市场反馈未接入","AI执行结果以独立分析记录为准，未生成时不补造摘要和影响推断"));return result;}
    public Object proof(UUID id){var proof=new LinkedHashMap<String,Object>(db.queryForMap("SELECT r.id,r.source_id,r.source_url,r.raw_content_hash,r.published_at,r.collected_at,r.first_seen_at,r.revision,s.name source_name,s.level,encode(sha256(r.raw_content),'hex')=r.raw_content_hash hash_valid FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id WHERE r.id=?",id));proof.put("responses",db.queryForList("SELECT o.id,o.url,o.response_status,o.sha256,o.acquired_at,x.section,octet_length(o.raw_content) response_bytes FROM response_evidence x JOIN official_response o ON o.id=x.response_id WHERE x.evidence_id=? ORDER BY o.acquired_at DESC LIMIT 20",id));return proof;}
    public Object entities(int page){if(page<0||page>100000)throw new IllegalArgumentException("页码无效");return db.queryForList("SELECT * FROM financial_entity ORDER BY status DESC,official_name,id LIMIT 50 OFFSET ?",page*50);}
    public Object relations(){return db.queryForList("SELECT r.*,a.official_name subject,b.official_name object FROM entity_relation r JOIN financial_entity a ON a.id=r.subject_id JOIN financial_entity b ON b.id=r.object_id ORDER BY r.id LIMIT 100");}
    public Object macro(String series,int page){if(series==null||series.length()>100||page<0||page>10000)throw new IllegalArgumentException("指标查询无效");return Map.of("series",db.queryForList("SELECT m.*,o.url source_url,o.sha256 response_hash,o.acquired_at FROM macro_series m JOIN official_response o ON o.id=m.response_id ORDER BY m.id"),"observations",db.queryForList("SELECT * FROM (SELECT DISTINCT ON(series_id,observation_date) o.*,r.collected_at,r.raw_content_hash,r.source_url FROM macro_observation o JOIN raw_evidence r ON r.id=o.evidence_id WHERE (?='' OR series_id=?) ORDER BY series_id,observation_date,version DESC) t ORDER BY observation_date DESC,series_id LIMIT 100 OFFSET ?",series,series,page*100),"versions",db.queryForList("SELECT series_id,count(*) versions,count(DISTINCT observation_date) dates FROM macro_observation GROUP BY series_id ORDER BY series_id"));}
    @Transactional public void link(UUID event,UUID evidence,String reason){validateReason(reason);db.queryForObject("SELECT id FROM financial_event WHERE id=?",UUID.class,event);official(evidence);db.update("INSERT INTO candidate_official_evidence(event_id,evidence_id,reason) VALUES(?,? ,?) ON CONFLICT(event_id,evidence_id) DO UPDATE SET reason=excluded.reason",event,evidence,reason);db.update("INSERT INTO research_review(target_type,target_id,actor,decision,reason,evidence_id) VALUES('EVENT',?,'local-admin','LINK_OFFICIAL_EVIDENCE',?,?)",event,reason,evidence);}
    private void official(UUID evidence){if(evidence==null)throw new IllegalArgumentException("请选择已有的官方证据");if(!Boolean.TRUE.equals(db.queryForObject("SELECT s.level='L0' AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND l.status='APPROVED' AND l.access_allowed AND l.storage_allowed AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=r.source_id WHERE r.id=?",Boolean.class,evidence)))throw new IllegalArgumentException("需要许可有效且哈希一致的官方证据");}
    private static void validateReason(String reason){if(reason==null||reason.strip().length()<10||reason.length()>2000)throw new IllegalArgumentException("请提供10至2000字审核依据");}
    @Transactional public UUID relation(UUID subject,UUID object,String type,UUID evidence,String explanation,Instant effectiveFrom,Instant effectiveUntil){validateReason(explanation);if(subject.equals(object)||effectiveFrom!=null&&effectiveUntil!=null&&!effectiveUntil.isAfter(effectiveFrom))throw new IllegalArgumentException("关系主体或有效区间无效");if(evidence!=null)db.queryForObject("SELECT id FROM raw_evidence WHERE id=?",UUID.class,evidence);UUID id=UUID.randomUUID();db.update("INSERT INTO entity_relation(id,subject_id,object_id,type,evidence_id,explanation,effective_from,effective_until) VALUES(?,?,?,?,?,?,?,?)",id,subject,object,type,evidence,explanation,effectiveFrom==null?null:java.sql.Timestamp.from(effectiveFrom),effectiveUntil==null?null:java.sql.Timestamp.from(effectiveUntil));if("INDUSTRY".equals(type))db.update("UPDATE entity_relation SET relation_kind='INDUSTRY_MEMBERSHIP' WHERE id=?",id);if(type.startsWith("ACCOUNTING_"))db.update("UPDATE entity_relation SET relation_kind='ACCOUNTING_CONSOLIDATION' WHERE id=?",id);if("LEGAL_IDENTITY".equals(type))db.update("UPDATE entity_relation SET relation_kind='LEGAL_IDENTITY' WHERE id=?",id);if("MACRO_SENSITIVITY".equals(type))db.update("UPDATE entity_relation SET relation_kind='MACRO_HYPOTHESIS' WHERE id=?",id);db.update("INSERT INTO research_review(target_type,target_id,actor,decision,reason,evidence_id) VALUES('RELATION',?,'local-admin','PENDING',?,?)",id,explanation,evidence);return id;}
    @Transactional public void review(String target,UUID id,String decision,UUID evidence,String reason,String quote){validateReason(reason);if("RELATION".equals(target)&&"VERIFIED".equals(decision)&&!Set.of("BUSINESS_FACT","INDUSTRY_MEMBERSHIP").contains(db.queryForObject("SELECT relation_kind FROM entity_relation WHERE id=?",String.class,id)))throw new IllegalArgumentException("影响假设或统计候选不能作为已核实企业业务关系");if(id==null||target==null||decision==null||!Set.of("VERIFIED","CONFLICT","REJECTED","EXPIRED").contains(decision)||!Set.of("RELATION","EVENT").contains(target)||target.equals("EVENT")&&decision.equals("EXPIRED"))throw new IllegalArgumentException("审核类型无效");
        if(decision.equals("VERIFIED")){official(evidence);if(quote==null||quote.strip().length()<10||quote.length()>2000)throw new IllegalArgumentException("请提供官方证据原文摘录");String raw=new String(db.queryForObject("SELECT raw_content FROM raw_evidence WHERE id=?",byte[].class,evidence),java.nio.charset.StandardCharsets.UTF_8);if(!raw.contains(quote))throw new IllegalArgumentException("摘录不在实际证据中");if(target.equals("EVENT")&&db.queryForObject("SELECT count(*) FROM candidate_official_evidence WHERE event_id=? AND evidence_id=?",Integer.class,id,evidence)==0)throw new IllegalArgumentException("请先关联官方证据并核对同一事实");}
        if(target.equals("RELATION")&&decision.equals("VERIFIED")){new RelationReviewService(db).review(id,new RelationReviewService.Review("ACCEPT","local-admin",reason,evidence,quote,"人工审核只覆盖当前披露的关系及适用区间"));return;}
        if(target.equals("RELATION")){var row=db.queryForMap("SELECT * FROM entity_relation WHERE id=? FOR UPDATE",id);Object published=evidence==null?null:db.queryForObject("SELECT published_at FROM raw_evidence WHERE id=?",java.sql.Timestamp.class,evidence);if(decision.equals("VERIFIED")&&published==null)throw new IllegalArgumentException("已核实关系必须具备真实披露时间");db.update("UPDATE entity_relation SET status=?,evidence_id=COALESCE(?,evidence_id),first_public_at=COALESCE(first_public_at,?),disclosed_at=COALESCE(?,disclosed_at) WHERE id=?",decision,evidence,published,published,id);}else{int updated=db.update("UPDATE event_candidate SET verification=? WHERE event_id=?",decision,id);if(updated!=1)throw new IllegalArgumentException("研究候选不存在");if(evidence!=null)db.update("UPDATE candidate_official_evidence SET status=? WHERE event_id=? AND evidence_id=?",decision,id,evidence);}
        db.update("INSERT INTO research_review(target_type,target_id,actor,decision,reason,evidence_id) VALUES(?,?,'local-admin',?,?,?)",target,id,decision,reason+(quote==null?"":"\n证据摘录："+quote),evidence);
    }
}
